```tsx
import { useId } from "react";
import "./FocusProgress.css";

export interface FocusProgressProps {
  label: string;
  elapsedMinutes: number;
  totalMinutes: number;
}

export function FocusProgress({
  label,
  elapsedMinutes,
  totalMinutes,
}: FocusProgressProps) {
  const labelId = useId();

  // Normalise inputs so bad values can never produce an invalid bar.
  const total =
    Number.isFinite(totalMinutes) && totalMinutes > 0
      ? Math.round(totalMinutes)
      : 0;
  const elapsed = Number.isFinite(elapsedMinutes)
    ? Math.min(Math.max(Math.round(elapsedMinutes), 0), total)
    : 0;

  const fraction = total > 0 ? elapsed / total : 0;
  const remaining = total - elapsed;
  const complete = total > 0 && elapsed >= total;
  const valueText = `${elapsed} of ${total} minutes elapsed, ${remaining} remaining`;

  return (
    <div className="focus-progress" data-complete={complete || undefined}>
      <div className="focus-progress__header">
        <span id={labelId} className="focus-progress__label">
          {label}
        </span>
        <span className="focus-progress__count" aria-hidden="true">
          {elapsed}/{total} min
        </span>
      </div>
      <div
        className="focus-progress__track"
        role="progressbar"
        tabIndex={0}
        aria-labelledby={labelId}
        aria-valuemin={0}
        aria-valuemax={total}
        aria-valuenow={elapsed}
        aria-valuetext={valueText}
      >
        <div
          className="focus-progress__fill"
          style={{ transform: `scaleX(${fraction})` }}
        />
      </div>
    </div>
  );
}
