/*
 * FocusProgress styles.
 * Day is the default. Night applies when an ancestor carries
 * data-theme="night" (set on <html> or <body> by the app shell).
 * Colours are defined as local variables so the component
 * renders correctly even if global tokens are absent.
 */

.focus-progress {
  --fp-text: #1f2a2e;
  --fp-text-muted: #5b6b70;
  --fp-track: #e2ddd1;
  --fp-track-border: #cfc8b8;
  --fp-fill: #3c7a6e;
  --fp-fill-complete: #2f6b4f;
  --fp-focus: #1d4ed8;

  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  width: 100%;
  color: var(--fp-text);
  font-family: inherit;
}

[data-theme="night"] .focus-progress {
  --fp-text: #e6e9ee;
  --fp-text-muted: #9aa5b1;
  --fp-track: #2a303a;
  --fp-track-border: #3a4250;
  --fp-fill: #7fb8a8;
  --fp-fill-complete: #a8d8c6;
  --fp-focus: #9cc9ff;
}

.focus-progress__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.focus-progress__label {
  font-size: 1rem;
  font-weight: 500;
  overflow-wrap: anywhere;
}

.focus-progress__count {
  flex-shrink: 0;
  font-size: 0.875rem;
  font-variant-numeric: tabular-nums;
  color: var(--fp-text-muted);
}

.focus-progress__track {
  position: relative;
  height: 0.625rem;
  width: 100%;
  overflow: hidden;
  border-radius: 999px;
  background: var(--fp-track);
  box-shadow: inset 0 0 0 1px var(--fp-track-border);
  cursor: default;
}

.focus-progress__track:focus-visible {
  outline: 2px solid var(--fp-focus);
  outline-offset: 3px;
}

.focus-progress__fill {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: var(--fp-fill);
  transform-origin: left center;
  transition: transform 300ms ease-out;
}

.focus-progress[data-complete] .focus-progress__fill {
  background: var(--fp-fill-complete);
}

@media (prefers-reduced-motion: reduce) {
  .focus-progress__fill {
    transition: none;
  }
}

@media (forced-colors: active) {
  .focus-progress__track {
    border: 1px solid CanvasText;
    box-shadow: none;
    background: Canvas;
  }

  .focus-progress__fill {
    background: Highlight;
  }

  .focus-progress__track:focus-visible {
    outline-color: Highlight;
  }
}
